// Prepare writable storage for version components as required by the API
unsigned int major = 0, minor = 0, micro = 0;

// Call the target function with valid non-null pointers
hb_version(&major, &minor, &micro);

// Basic sanity checks as soft validation; do not assume specific ranges
// The API guarantees outputs are written; if any remain unmodified it would indicate an issue
// (We avoid hard assertions here to not over-constrain legitimate implementations.)
(void)major; (void)minor; (void)micro;

// Validation: This stub ensures non-null writable pointers are provided and exercises the function's output-only behavior.

// Invoke the target function; returned pointer is owned by the library and must not be freed or modified
const char *vs = hb_version_string();

// Use the string in a benign way to keep it live; ensure it is NUL-terminated by scanning up to a small bound
// (No deref beyond small bound to be safe in fuzzing environment.)
size_t observed_len = 0;
if (vs) {
    for (; observed_len < 64 && vs[observed_len] != '\0'; ++observed_len) {}
}
(void)observed_len;

// Validation: The stub retrieves the immutable version string and treats it as read-only without assuming lifetime beyond the call.

// Obtain the actual runtime version to construct inputs that exercise both true/false paths
unsigned int rmaj = 0, rmin = 0, rmic = 0;
hb_version(&rmaj, &rmin, &rmic);

// Choose a scenario: equal, lower-than, or greater-than the runtime version
unsigned int choice = *FUZZ_PARAM(unsigned int) % 3;
unsigned int qmaj = rmaj, qmin = rmin, qmic = rmic;
if (choice == 0) {
    // Equal: expect true
} else if (choice == 1) {
    // Lower-than runtime: decrement safely to ensure provided version <= runtime
    if (qmic > 0) {
        qmic -= 1;
    } else if (qmin > 0) {
        qmin -= 1; qmic = 0;
    } else if (qmaj > 0) {
        qmaj -= 1; qmin = 0; qmic = 0;
    } else {
        // Already at 0.0.0; keep equal scenario implicitly
    }
} else {
    // Greater-than runtime: bump micro by a small random delta to exceed runtime
    unsigned int delta = 1 + (*FUZZ_PARAM(unsigned int) % 10);
    qmic = rmic + delta;
}

hb_bool_t res = hb_version_atleast(qmaj, qmin, qmic);

// Property-based validation: compare against our constructed relation
int expect_true = 0;
if (qmaj < rmaj) expect_true = 1;
else if (qmaj > rmaj) expect_true = 0;
else if (qmin < rmin) expect_true = 1;
else if (qmin > rmin) expect_true = 0;
else if (qmic <= rmic) expect_true = 1;
else expect_true = 0;

FUZZ_ASSERT((!!res) == expect_true, "hb_version_atleast must reflect lexicographic version comparison against runtime version");

// Validation: The stub deterministically exercises both success and failure cases and asserts equivalence with lexicographic version ordering.

