hb_tag_to_string(tag, buf4);

// Provide a random tag and a writable buffer of at least 4 bytes as required.
hb_tag_t tag = (hb_tag_t)*FUZZ_PARAM(uint32_t);
char buf4[4];
// API requires exactly 4 writable bytes; no NUL terminator implied.
